                        renderRegions();
                        saveRegionsToLocal();
                    }

                    scheduleAutoSync();

                    // Message de confirmation
                    if (shouldReplace) {
                        let confirmMessage = "Import réussi !\n";
                        if (addedLocations > 0) confirmMessage += `- ${addedLocations} lieux importés\n`;
                        if (addedRegions > 0) confirmMessage += `- ${addedRegions} régions importées\n`;
